class Solution {
public:
    int isWinner(std::vector<int>& player1, std::vector<int>& player2) {
        auto getScore = [](const std::vector<int>& p) {
            int total = 0;
            for (int i = 0; i < (int)p.size(); i++) {
                int mult = ((i > 0 && p[i - 1] == 10) || (i > 1 && p[i - 2] == 10)) ? 2 : 1;
                total += mult * p[i];
            }
            return total;
        };
        int s1 = getScore(player1), s2 = getScore(player2);
        if (s1 > s2) return 1;
        if (s2 > s1) return 2;
        return 0;
    }
};

class Solution {
    public int isWinner(int[] player1, int[] player2) {
        int s1 = getScore(player1), s2 = getScore(player2);
        if (s1 > s2) return 1;
        if (s2 > s1) return 2;
        return 0;
    }

    private int getScore(int[] p) {
        int total = 0;
        for (int i = 0; i < p.length; i++) {
            int mult = ((i > 0 && p[i - 1] == 10) || (i > 1 && p[i - 2] == 10)) ? 2 : 1;
            total += mult * p[i];
        }
        return total;
    }
}

